INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷80·晋高祖本纪·天福六年八月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7ec152ca6b93afb639ad0febcd3c8be43a631b52/content/books/zizhi-tongjian/vol-284/year-0945/part-02/sources/library/jiuwudaishi-080-941-deqing/source.txt", "note": "《旧五代史》卷80·晋高祖本纪·天福六年八月，段落 jiu-wudaishi-205deb4a7860-p001961；上下文、卷年与传主已校核，纸本及异文待核。", "id": "f07378ff-e8ee-5043-9cbe-aa95fbab891c"}, {"title": "旧五代史·卷83·晋少帝本纪·开运二年二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7ec152ca6b93afb639ad0febcd3c8be43a631b52/content/books/zizhi-tongjian/vol-284/year-0945/part-02/sources/library/jiuwudaishi-083-945-february/source.txt", "note": "《旧五代史》卷83·晋少帝本纪·开运二年二月，段落 jiu-wudaishi-205deb4a7860-p002019；上下文、卷年与传主已校核，纸本及异文待核。", "id": "bcfd9fca-c2ef-5239-a1fe-245cbdf00fdb"}, {"title": "旧五代史·卷83·晋少帝本纪·开运二年三月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7ec152ca6b93afb639ad0febcd3c8be43a631b52/content/books/zizhi-tongjian/vol-284/year-0945/part-02/sources/library/jiuwudaishi-083-945-march/source.txt", "note": "《旧五代史》卷83·晋少帝本纪·开运二年三月，段落 jiu-wudaishi-205deb4a7860-p002020；上下文、卷年与传主已校核，纸本及异文待核。", "id": "fe241d3b-a2e9-5a28-ab85-e8715cedb7a1"}, {"title": "辽史·卷4·太宗本纪·会同八年三月", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7ec152ca6b93afb639ad0febcd3c8be43a631b52/content/books/zizhi-tongjian/vol-284/year-0945/part-02/sources/library/liaoshi-004-945-march/source.txt", "note": "《辽史》卷4·太宗本纪·会同八年三月，段落 liaoshi-7cd182a20e67-p000557；上下文、卷年与传主已校核，纸本及异文待核。", "id": "23623d25-c3e3-52e4-917e-04a37b41c2f7"}, {"title": "资治通鉴·卷284·开运二年二月至三月（后续福州政变与北征留后续）", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7ec152ca6b93afb639ad0febcd3c8be43a631b52/content/books/zizhi-tongjian/vol-284/year-0945/part-02/sources/library/tongjian-284-945-february-march/source.txt", "note": "《资治通鉴》卷284·开运二年二月至三月（后续福州政变与北征留后续），段落 zizhi-tongjian-a63549944a71-p003379；上下文、卷年与传主已校核，纸本及异文待核。", "id": "6c12b2ff-62fc-5257-9c04-68d33dba15eb"}, {"title": "新五代史·卷29·桑维翰传·冯玉李彦韬争权", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7ec152ca6b93afb639ad0febcd3c8be43a631b52/content/books/zizhi-tongjian/vol-284/year-0945/part-02/sources/library/xinwudaishi-029-sang-feng-strife/source.txt", "note": "《新五代史》卷29·桑维翰传·冯玉李彦韬争权，段落 xin-wudaishi-b08f244b9241-p001061；上下文、卷年与传主已校核，纸本及异文待核。", "id": "971dc8a0-75e9-5a4b-b734-f76cfb59d1e1"}, {"title": "新五代史·卷33·沈斌传·字与籍贯及早年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7ec152ca6b93afb639ad0febcd3c8be43a631b52/content/books/zizhi-tongjian/vol-284/year-0945/part-02/sources/library/xinwudaishi-033-shen-origins/source.txt", "note": "《新五代史》卷33·沈斌传·字与籍贯及早年，段落 xin-wudaishi-b08f244b9241-p001197；上下文、卷年与传主已校核，纸本及异文待核。", "id": "0c03249e-dabd-56bd-a490-ac1acd357929"}, {"title": "新五代史·卷33·沈斌传·祁州失守", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7ec152ca6b93afb639ad0febcd3c8be43a631b52/content/books/zizhi-tongjian/vol-284/year-0945/part-02/sources/library/xinwudaishi-033-shen-qizhou/source.txt", "note": "《新五代史》卷33·沈斌传·祁州失守，段落 xin-wudaishi-b08f244b9241-p001198；上下文、卷年与传主已校核，纸本及异文待核。", "id": "d50017f6-86d2-58bb-a90b-1b2f58cdbb70"}, {"title": "资治通鉴·卷284·开运二年正月（后续段落不在本批处理）", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ac10110d193f69ce3499423e4fa4db294584e2ff/content/books/zizhi-tongjian/vol-284/year-0945/part-01/sources/library/tongjian-284-945-january/source.txt", "note": "《资治通鉴》卷284·开运二年正月（后续段落不在本批处理），段落 zizhi-tongjian-a63549944a71-p003378；已核上下文及传主，纸本及异文待核。", "id": "ddb8024d-0bbc-52da-9f92-29f566603fcb"}, {"title": "旧五代史·卷83·晋少帝本纪·开运二年正月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ac10110d193f69ce3499423e4fa4db294584e2ff/content/books/zizhi-tongjian/vol-284/year-0945/part-01/sources/library/jiuwudaishi-083-945-january/source.txt", "note": "《旧五代史》卷83·晋少帝本纪·开运二年正月，段落 jiu-wudaishi-205deb4a7860-p002018；已核上下文及传主，纸本及异文待核。", "id": "58659c8a-2ea0-5594-bf3f-81d582ec60ca"}, {"title": "新五代史·卷9·晋本纪第九·出帝开运二年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ac10110d193f69ce3499423e4fa4db294584e2ff/content/books/zizhi-tongjian/vol-284/year-0945/part-01/sources/library/xinwudaishi-009-945/source.txt", "note": "《新五代史》卷9·晋本纪第九·出帝开运二年，段落 xin-wudaishi-b08f244b9241-p000336；已核上下文及传主，纸本及异文待核。", "id": "e3160060-6159-5733-9a3f-cd13016527db"}, {"title": "新五代史·卷62·南唐世家·保大二年闽乱与攻建州", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b20c86dd55e2fffd503cfcda0a449be32dd9edc8/content/books/zizhi-tongjian/vol-284/year-0944/part-06/sources/library/xinwudaishi-062-min-campaign/source.txt", "note": "《新五代史》卷62·南唐世家·保大二年闽乱与攻建州，段落 xin-wudaishi-b08f244b9241-p003141；卷界、年界与传主已按上下文校核，纸本及异文待核。", "id": "34d65449-472f-5f0f-9f16-f936571d7693"}, {"title": "旧五代史·卷七十三", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2f3733ce/content/books/zizhi-tongjian/vol-269/year-0915/part-09/sources/library/jiuwudaishi-073-wen-tao/source.txt", "note": "《旧五代史》卷七十三，段落 jiu-wudaishi-205deb4a7860-p001845；EPUB电子本，纸本及异文待核", "id": "a36042d4-bf0d-5740-8068-1c9314a50310"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "马全节", "aliases": ["馬全節"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马全节，金州防御使、以私财给军并拒战者。", "biography": null, "status": "draft", "id": "bb5608d9-eabe-58ce-8c56-b07e57faadb5"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "王继昌", "aliases": ["王繼昌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王延政的从子，任门下侍郎、同平章事。945年王延政因南唐来攻而暂不迁都，任他都督南都内外诸军事，驻福州。父亲姓名及生卒年本次引文未载。", "biography": null, "status": "draft", "id": "8f9c1ae4-de5b-55c7-a1f1-0764d9c37826"}, {"name": "黄仁讽", "aliases": ["黃仁諷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国飞捷指挥使。945年王延政任他为镇遏使，率军作为王继昌的后援。生卒年本段未载。", "biography": null, "status": "draft", "id": "c3e8e01d-6411-59a0-8486-93d2b678ca18"}, {"name": "林仁翰", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "福州南廊承旨。944年闰十二月丁酉率部反对连重遇与朱文进，杀连重遇后号召众人杀朱文进。《新五代史》称他为裨将。生卒年本段未载。", "biography": null, "status": "draft", "id": "b422146c-60a6-5f7b-ba8e-b77da41f898d"}, {"name": "安审琦", "aliases": ["安審琦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安审琦，彰圣都指挥使、领顺化节度使者。", "biography": null, "status": "draft", "id": "a579a6a1-65a5-5c8a-9c6c-be178cb049aa"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "沈斌", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 945, "description": "字安时，徐州下邳人，曾任梁拱辰都指挥使，后唐从魏王李继岌伐蜀、平康延孝。开运元年任后晋祁州刺史，945年契丹攻祁州后死亡。主书和新史传记写自杀，《辽史》写被杀，具体日期按各书分别保留。出生年未载。", "biography": null, "status": "draft", "id": "0f2d3100-a2ca-5d11-9dc8-c7b5402097c4"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "冯玉", "aliases": ["馮玉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯皇后的兄长，后晋官员。《资治通鉴》记其由礼部郎中、盐铁判官被迅速擢为端明殿学士、户部侍郎；《旧五代史》另记知制诰、中书舍人、颍州团练使等任职。各书路径分别保留，生卒年本批未核。", "biography": null, "status": "draft", "id": "b4626ebf-1219-5b9b-baca-73e491e175f8"}, {"name": "李彦韬（后晋宣徽使）", "aliases": ["李彥韜（後晉宣徽使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，早年曾侍奉阎宝，后来入石敬瑭帐下并留在太原侍奉石重贵。945年任宣徽北院使、暂代侍卫马步都虞候，与冯玉争桑维翰的权力。与早期曾名李彦韬的温韬分档，温韬在后唐明宗时已被赐死。生卒年本段未载。", "biography": null, "status": "draft", "id": "e4ac4a2d-843f-5686-98da-4b16e23f906d"}, {"name": "桑维翰", "aliases": ["桑維翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：桑维翰，主张自全、求援者。", "biography": null, "status": "draft", "id": "5132e50a-3ce2-55d5-8f89-fdccd6bf4f02"}, {"name": "李崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：李崧。", "biography": null, "status": "draft", "id": "42727c37-29c7-534f-b0f7-900992c16def"}, {"name": "刘昫", "aliases": ["劉昫", "刘煦", "劉煦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘昫，端明殿学士、受相职者。", "biography": null, "status": "draft", "id": "b63eeed9-ecc3-575d-aba8-41b03e6caa3e"}, {"name": "阎宝", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷262光化三年条所见人物：阎宝。", "biography": null, "status": "draft", "id": "3d9c3ea7-8a06-5aef-a25d-b71110ca2658"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "查文徽", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "休宁人，南唐官员。943年李璟即位后，史书记他与陈觉、冯延巳、冯延鲁、魏岑互相引荐，不久与魏岑同任枢密副使。当时五人被称为五鬼，称呼按史书记载保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "b0abcb8a-3aa7-5d58-8f3c-79f4fc15b117"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "何敬洙", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐天威都虞候。945年李璟任他为建州行营招讨马步都指挥使，与祖全恩、姚凤率数千兵增援查文徽，攻建州。生卒年本段未载。", "biography": null, "status": "draft", "id": "775d369d-2375-51d0-bcd1-b59c3a78d7c1"}, {"name": "祖全恩", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领。李昪命他带兵迎接逃往吴国的卢文进，并告诫在城外接应、不得抢掠。本处是回述此前经历，具体日期未载。生卒年未载。", "biography": null, "status": "draft", "id": "9e06353a-5151-57d8-9194-a100cc1ce8eb"}, {"name": "姚凤", "aliases": ["姚鳳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领。945年李璟任他为建州行营都监，与何敬洙、祖全恩率军增援查文徽。生卒年本段未载。", "biography": null, "status": "draft", "id": "74f180a4-a1e3-5952-a5d4-9d936d1a19ac"}, {"name": "杨思恭", "aliases": ["楊思恭"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "建阳人，王延政属下的节度巡官。943年王延政建殷后任兵部尚书，不久升仆射、录军国事。史书记他加重田亩山泽及鱼盐蔬果税负，记载当时人称他为杨剥皮。生卒年尚未核。", "biography": null, "status": "draft", "id": "588de476-95b1-534e-af0e-97b68a1f83a0"}, {"name": "陈望", "aliases": ["陳望"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王延政部将。942年与包洪实率水军抵御福州军，七月丁酉在尤口与对方交战。生卒年未载。", "biography": null, "status": "draft", "id": "1129ee15-bc93-5f0e-bb19-5143390129ac"}, {"name": "董思安", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州军中将领。944年参与反朱文进的谋议和泉州政变，后被王延政任为都指挥使。生卒年本段未载。", "biography": null, "status": "draft", "id": "385e66d6-1650-5db4-a215-4208ca968420"}, {"name": "王忠顺", "aliases": ["王忠順"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州军中将领。944年与留从效、董思安、张汉思议反朱文进政权，参与泉州政变后被王延政任为都指挥使。生卒年本段未载。", "biography": null, "status": "draft", "id": "5c73751d-6af3-5516-935f-53a4ace23f02"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

